  await Promise.all([
    page.waitForEvent('domcontentloaded'),
    triage.locator(`[${STARTUP_FAILURE_TRIAGE_RELOAD}]`).click(),
  ]);
  await page.waitForFunction(() => window.__app?.ready === true);

  await expect(page).toHaveURL(target);
