test('Contracts keeps an operation grant toggle focused and single-flight', async ({ page }) => {
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto(
    `${HARNESS_URL}?contracts=paged&hold_rpc=contract.grant.write#contracts/door_paged_01/ops`,
  );
  await page.waitForFunction(() => window.__app?.ready === true);

  const toggle = page.locator(
    '[data-recued-contract-grants-cell-toggle]',
  ).first();
  await expect(toggle).toBeVisible();
  const startedChecked = await toggle.isChecked();
  await page.evaluate(() => {
    document.documentElement.setAttribute('data-audit-confirm-count', '0');
    window.confirm = (message?: string): boolean => {
      const root = document.documentElement;
      const count = Number(root.getAttribute('data-audit-confirm-count') ?? '0');
      root.setAttribute('data-audit-confirm-count', String(count + 1));
      root.setAttribute('data-audit-confirm-message', message ?? '');
      return false;
    };
  });
  await toggle.focus();
  await page.keyboard.press('Space');

  await expect(toggle).toHaveAttribute('aria-disabled', 'true');
  await expect(toggle).toHaveAttribute('aria-busy', 'true');
  await page.evaluate(() => window.__app.setHash('#data'));
  const html = page.locator('html');
  await expect(html).toHaveAttribute(
    'data-audit-confirm-message',
    'Something is still happening. Leave anyway?',
  );
  await expect(page).toHaveURL(/#contracts\/door_paged_01\/ops$/);
  await expect(toggle).not.toHaveAttribute('disabled');
  await expect(toggle).toBeFocused();
  await toggle.dispatchEvent('change');
  await toggle.dispatchEvent('change');
  await expect.poll(
    () => page.evaluate(() => window.__app.rpcCallCount('contract.grant.write')),
  ).toBe(1);
  expect(await page.evaluate(
    () => window.__app.releaseRpcResponses?.('contract.grant.write'),
  )).toBe(1);

  await expect(toggle).not.toHaveAttribute('aria-disabled');
  await expect(toggle).not.toHaveAttribute('aria-busy');
  await expect(toggle).toBeFocused();
  expect(await toggle.isChecked()).toBe(!startedChecked);
  await page.evaluate(() => window.__app.setHash('#data'));
  await expect(page).toHaveURL(/#data$/);
  await expect(html).toHaveAttribute('data-audit-confirm-count', '1');
});

test('an uncertain run lands on its exact record with readable dark-theme next steps', async ({ page }) => {
  await page.setViewportSize({ width: 320, height: 800 });
  await page.goto(`${HARNESS_URL}?chat=session&journey=verification`);
  await page.waitForFunction(() => window.__app?.ready === true);
  await page.evaluate(() => {
    document.documentElement.dataset.theme = 'dark';
    window.__app.setHash(
      '#logs/run-verify/return/chat/session/chat_1/plan/'
      + 'plan_email_1/answer/msg_action',
    );
  });

  const outcome = page.locator(`[${LOGS_OUTCOME}]`);
  await expect(outcome).toBeVisible();
  await expect(outcome).toContainText('Somebody needs to check what happened');
  await expect(outcome).toBeFocused();
  const openRun = page.getByRole('button', {
    name: 'Open run detail for Schedule customer review (run-verify)',
    exact: true,
  });
  const openRunBox = await openRun.boundingBox();
  expect(openRunBox?.width).toBeGreaterThanOrEqual(32);
  expect(openRunBox?.height).toBeGreaterThanOrEqual(32);
  const detailLinkHeights = await page
    .locator('.logs-row-links a, .logs-detail-meta a')
    .evaluateAll((links) =>
      links.map((link) => link.getBoundingClientRect().height)
    );
  expect(detailLinkHeights.length).toBeGreaterThan(0);
  expect(Math.min(...detailLinkHeights)).toBeGreaterThanOrEqual(24);

  const affected = page.locator(`[${LOGS_AFFECTED_ITEMS}]`);
  const verify = affected.getByRole('link', {
    name: 'Check before running it again',
  });
  await expect(verify).toBeVisible();
  await verify.click();

  const heading = page.locator(`[${DATA_DETAIL_HEADING}]`);
  await expect(heading).toBeVisible();
  await expect(heading).toHaveText('Customer review');
  await expect(heading).toHaveAttribute('tabindex', '-1');
  await expect(heading).toBeFocused();
  await expect(
    page.getByRole('heading', { name: 'Customer review', level: 2 }),
  ).toBeVisible();

  const primary = page.locator(
    `[${DATA_VERIFICATION_ACTION}="reviewed"]`,
  );
  await expect(primary).toBeVisible();
  const contrast = await page.evaluate(
    ({ primarySelector }) => {
      const parse = (value: string): [number, number, number] => {
        const numbers = value.match(/[\d.]+/g)?.map(Number) ?? [];
        return [numbers[0] ?? 0, numbers[1] ?? 0, numbers[2] ?? 0];
      };
      const luminance = (value: string): number => {
        const [r, g, b] = parse(value).map((channel) => {
          const normalized = channel / 255;
          return normalized <= 0.04045
            ? normalized / 12.92
            : ((normalized + 0.055) / 1.055) ** 2.4;
        }) as [number, number, number];
        return 0.2126 * r + 0.7152 * g + 0.0722 * b;
      };
      const ratio = (fg: string, bg: string): number => {
        const first = luminance(fg);
        const second = luminance(bg);
        return (Math.max(first, second) + 0.05)
          / (Math.min(first, second) + 0.05);
      };
      const backgroundFor = (node: Element): string => {
        let candidate: Element | null = node;
        while (candidate !== null) {
          const background = getComputedStyle(candidate).backgroundColor;
          const channels = background.match(/[\d.]+/g)?.map(Number) ?? [];
          if ((channels[3] ?? 1) > 0) return background;
          candidate = candidate.parentElement;
        }
        return getComputedStyle(document.body).backgroundColor;
      };
      const measure = (): {
        value: number;
        label: number;
        action: number;
      } => {
        const value = document.querySelector(
          '.col-explorer-detail-field dd',
        );
        const label = document.querySelector(
          '.col-explorer-detail-field dt',
        );
        const action = document.querySelector(primarySelector);
        if (value === null || label === null || action === null) {
          throw new Error('verification contrast targets missing');
        }
        const actionStyle = getComputedStyle(action);
        return {
          value: ratio(getComputedStyle(value).color, backgroundFor(value)),
          label: ratio(getComputedStyle(label).color, backgroundFor(label)),
          action: ratio(actionStyle.color, actionStyle.backgroundColor),
        };
      };
      const dark = measure();
      document.documentElement.dataset.theme = 'light';
      const light = measure();
      document.documentElement.dataset.theme = 'dark';
      return {
        dark,
        light,
        pageWidth: document.documentElement.scrollWidth,
        viewport: window.innerWidth,
      };
    },
    {
      primarySelector:
        `[${DATA_VERIFICATION_ACTION}="reviewed"]`,
    },
  );
  for (const theme of [contrast.light, contrast.dark]) {
    expect(theme.value).toBeGreaterThanOrEqual(4.5);
    expect(theme.label).toBeGreaterThanOrEqual(4.5);
    expect(theme.action).toBeGreaterThanOrEqual(4.5);
  }
  expect(contrast.pageWidth).toBeLessThanOrEqual(contrast.viewport);
  const rawDetails = page.locator('.col-explorer-detail-raw');
  const rawSummary = page.locator('.col-explorer-detail-raw summary');
  expect((await rawSummary.boundingBox())?.height).toBeGreaterThanOrEqual(36);
  await rawSummary.focus();
  await page.keyboard.press('Enter');
  await expect(rawDetails).toHaveAttribute('open', '');
  await expect(rawSummary).toBeFocused();
  expect(await page.evaluate(
    () => document.documentElement.scrollWidth <= window.innerWidth,
  )).toBe(true);

  await primary.click();
  await expect(page).toHaveURL(
    /#chat\/session\/chat_1\/plan\/plan_email_1/,
  );
  await expect(page.locator('[data-recued-chat-route]')).toBeVisible();
  const runOutcome = page.locator('.chat-data-verification-run');
  await expect(runOutcome).toHaveText('See how the run ended →');
  expect((await runOutcome.boundingBox())?.height).toBeGreaterThanOrEqual(36);
  await runOutcome.focus();
  await expect(runOutcome).toBeFocused();
});

test('the shell owns one Run palette across routes and Ctrl+K opens it globally', async ({ page }) => {
  await page.setViewportSize({ width: 280, height: 653 });
  await page.goto(`${HARNESS_URL}?run_palette=autorun#data`);
  await page.waitForFunction(() => window.__app?.ready === true);

  const trigger = page.locator(`[${GLOBAL_RUN_PALETTE_TRIGGER}]`);
  await expect(trigger).toBeVisible();
  await expect(trigger).toHaveAttribute('aria-haspopup', 'dialog');
  await expect(trigger).toHaveAttribute(
    'aria-keyshortcuts',
    'Control+K Meta+K',
  );
  expect((await trigger.boundingBox())?.height).toBeGreaterThanOrEqual(44);
  const topbarGeometry = await page.locator(`[${SHELL_TOPBAR}]`).evaluate(
    (topbar) => {
      const rect = topbar.getBoundingClientRect();
      return {
        left: rect.left,
        right: rect.right,
        scrollWidth: topbar.scrollWidth,
        clientWidth: topbar.clientWidth,
        viewport: window.innerWidth,
      };
    },
  );
  expect(topbarGeometry.left).toBeGreaterThanOrEqual(-0.5);
  expect(topbarGeometry.right).toBeLessThanOrEqual(topbarGeometry.viewport + 0.5);
  expect(topbarGeometry.scrollWidth).toBeLessThanOrEqual(
    topbarGeometry.clientWidth,
  );

  const overlay = page.locator(`[${RUN_PALETTE}]`);
  await trigger.click();
  await expect(overlay).toHaveCount(1);
  await page.keyboard.press('Control+K');
  await expect(overlay).toHaveCount(1);
  expect(await overlay.evaluate((node) => node.contains(document.activeElement)))
    .toBe(true);
  await page.keyboard.press('Escape');
  await expect(overlay).toHaveCount(0);
  await expect(trigger).toBeFocused();

  const content = page.locator('[data-recued-webclient-content]');
  await content.focus();
  const composing = await content.evaluate((node) => {
    const event = new KeyboardEvent('keydown', {
      key: 'k',
      ctrlKey: true,
      isComposing: true,
      bubbles: true,
      cancelable: true,
    });
    const dispatched = node.dispatchEvent(event);
    return { dispatched, defaultPrevented: event.defaultPrevented };
  });
  expect(composing).toEqual({ dispatched: true, defaultPrevented: false });
  await expect(overlay).toHaveCount(0);

  await page.keyboard.press('Control+K');
  await expect(overlay).toHaveCount(1);
  await page.evaluate(() => window.__app.setHash('#settings'));
  await expect(page).toHaveURL(/#settings$/);
  await expect(overlay).toHaveCount(0);
  await expect(trigger).toBeVisible();

  await page.locator(`[${DRAWER_TOGGLE}]`).click();
  await page.locator(`[${DRAWER_ACTION}="create"]`).click();
  const createOverlay = page.locator(`[${CREATE_OVERLAY}]`);
  await expect(createOverlay).toBeVisible();
  await page.keyboard.press('Control+K');
  await expect(overlay).toHaveCount(0);
  await expect(createOverlay).toBeVisible();
  await page.keyboard.press('Escape');
  await expect(createOverlay).toHaveCount(0);

  await page.keyboard.press('Control+K');
  await expect(overlay).toHaveCount(1);
  await page.keyboard.press('Escape');
  await expect(overlay).toHaveCount(0);
});

