  expect(geometry.right).toBeLessThanOrEqual(geometry.viewportWidth - 15.5);

  const close = page.locator(`[${RUN_PALETTE_CLOSE}]`);
  const picker = dialog.getByRole('combobox', { name: 'Recipe' });
